window.LT = (id, vars) => {
  const [level, key] = String(id).split('.');
  const entry = window.PENINSULA_LEVEL_TEXTS[level]?.texts?.[key];
  if (!entry) { console.warn('Missing level text', id); return id; }
  return vars ? entry.text.replace(/\{(\w+)\}/g, (_, name) => vars[name] ?? '') : entry.text;
};
